import{_ as e,o as s,c as n,a2 as l}from"./chunks/framework.CHeM0PsO.js";const h=JSON.parse('{"title":"抽卡记录-原神、星铁、绝区零","description":"","frontmatter":{},"headers":[],"relativePath":"projects/lotus-plugin/docs/features/gacha-log.md","filePath":"projects/lotus-plugin/docs/features/gacha-log.md"}'),i={name:"projects/lotus-plugin/docs/features/gacha-log.md"};function o(t,a,p,r,c,d){return s(),n("div",null,[...a[0]||(a[0]=[l(`<h1 id="抽卡记录-原神、星铁、绝区零" tabindex="-1">抽卡记录-原神、星铁、绝区零 <a class="header-anchor" href="#抽卡记录-原神、星铁、绝区零" aria-label="Permalink to &quot;抽卡记录-原神、星铁、绝区零&quot;">​</a></h1><p>返回：<a href="./../daily-note.html">上一级</a> / <a href="./../README.html">文档目录</a> / <a href="./README.html">小功能索引</a></p><h2 id="功能特性" tabindex="-1">功能特性 <a class="header-anchor" href="#功能特性" aria-label="Permalink to &quot;功能特性&quot;">​</a></h2><ul><li>原神通过对应 profile 的 stoken 生成 <code>authkey</code>。</li><li>星铁使用 profile Cookie 登录官方抽卡统计活动，读取五星记录与各卡池抽数，不依赖 <code>authkey</code>。</li><li>绝区零优先使用 CK 直刷；只有获取或刷新抽卡链接时才生成 <code>authkey</code>。</li><li>星铁记录以官方稳定记录 ID 增量合并；重复更新不会重复叠加，活动 token 和 Cookie 不落盘。</li><li>星铁接口不提供完整三星、四星明细；Lotus 保存五星、累计已抽和当前垫抽，数据位于 <code>data/starRailGachaJson/&lt;qq&gt;/&lt;uid&gt;.json</code>。</li><li>缓存和数据路径都按 profile 对应的游戏 UID 区分。</li><li><code>更新全部抽卡记录</code> 会遍历当前用户可用 profile。</li></ul><h2 id="指令用法" tabindex="-1">指令用法 <a class="header-anchor" href="#指令用法" aria-label="Permalink to &quot;指令用法&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#更新抽卡记录[profile]</span></span>
<span class="line"><span>*更新抽卡记录[profile]</span></span>
<span class="line"><span>#星铁更新抽卡记录[profile]</span></span>
<span class="line"><span>%更新抽卡记录[profile]</span></span>
<span class="line"><span>#绝区零刷新抽卡链接[profile]</span></span>
<span class="line"><span>#绝区零更新抽卡记录[profile]</span></span>
<span class="line"><span>#更新全部抽卡记录</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h2 id="变量说明" tabindex="-1">变量说明 <a class="header-anchor" href="#变量说明" aria-label="Permalink to &quot;变量说明&quot;">​</a></h2><ul><li><code>profile</code>：可选，Lotus 内部 profile 序号，范围 <code>1..255</code>；普通单 profile 指令省略时会按 profile 1 的同一路由执行。</li></ul>`,8)])])}const f=e(i,[["render",o]]);export{h as __pageData,f as default};
